      "card_ids": ["C29"],
      "claim": "Paltusotine had 69% absolute oral bioavailability in healthy male participants after a 20 mg oral solution compared with IV, supporting high bioavailability."
    },
    {
      "card_ids": ["C02"],
      "claim": "Moxifloxacin absolute oral bioavailability was approximately 91% from an oral tablet in humans, supporting high bioavailability."
    },
    {
      "card_ids": ["C18"],
      "claim": "Veralipride absolute oral bioavailability was 78.63 ± 20.23% from oral capsules versus intravenous infusion in 12 subjects, supporting high bioavailability."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All usable evidence molecules show absolute oral bioavailability well above the 20% threshold, with direct human measurements for paltusotine, moxifloxacin, and veralipride; therefore the prediction is high.",
  "evidence_gaps": [
    "Molecule 4 contains records for different compounds (brigatinib and GSK1322322); these inconsistent cards were discounted and the provenance conflict remains unresolved.",
    "Some records are qualitative or predicted rather than directly measured absolute human bioavailability, but they do not contradict the positive direction."
  ],
